CREATE TABLE cliente (cliente_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nombre VARCHAR(255) NOT NULL, email VARCHAR(255), documento VARCHAR(255));
CREATE TABLE producto (producto_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, descripcion VARCHAR(255) NOT NULL, precio DECIMAL(19,2) NOT NULL, stock INTEGER NOT NULL);
CREATE TABLE comprobante (comprobante_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, fecha TIMESTAMP NOT NULL, total DECIMAL(19,2) NOT NULL, cantidad_total_productos INTEGER NOT NULL, cliente_id BIGINT NOT NULL, CONSTRAINT fk_comprobante_cliente FOREIGN KEY (cliente_id) REFERENCES cliente(cliente_id));
CREATE TABLE linea_comprobante (linea_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, cantidad INTEGER NOT NULL, precio_unitario DECIMAL(19,2) NOT NULL, subtotal DECIMAL(19,2) NOT NULL, producto_id BIGINT NOT NULL, comprobante_id BIGINT NOT NULL, CONSTRAINT fk_linea_producto FOREIGN KEY (producto_id) REFERENCES producto(producto_id), CONSTRAINT fk_linea_comprobante FOREIGN KEY (comprobante_id) REFERENCES comprobante(comprobante_id));
